"""Rerun four benchmark fixtures and build a local, dependency-free replay."""
from pathlib import Path
import sys,json,importlib.util,datetime
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'.deps/recovery-r1'))
from shapely import wkt
spec=importlib.util.spec_from_file_location('engine',ROOT/'research/assistance/linkage_engine.py')
engine=importlib.util.module_from_spec(spec);spec.loader.exec_module(engine)
OUT=ROOT/'output/assistance_live_demo';OUT.mkdir(exist_ok=True,parents=True)
manifest=json.loads((ROOT/'research/assistance/linkage_manifest_v1.json').read_text())
scenarios=[]
for b in manifest['blocks']:
 if b['slot']!=0:continue
 area=wkt.loads(b['geometry_wkt'])
 case=dict(name=b['block'],area=area,pairs=[(tuple(p['client_start']),tuple(p['helper_start']),p['client_nominal_speed'],p['helper_nominal_speed']) for p in b['pairs']],extras=[tuple(x) for x in b['extras']],goal=tuple(b['goal']),axis=b['exit_axis'],plane=b['exit_plane'])
 results={}
 for mode in ['threshold','independent']:
  r=engine.run(case,.005,mode,parameters={'strength_neighbor_repulsion':2.6},gain=1.)
  assert not r['failures'],r['failures']
  r['frames'].append(dict(t=r['clearance_s'],positions={},exited=list(range(1,r['occupants']+1))))
  results[mode]=r
 roles={str(i+1):dict(role='client' if i%2==0 else 'helper',radius=.30 if i%2==0 else .22,label=('C' if i%2==0 else 'H')+str(i//2+1)) for i in range(4)}
 for i in range(len(b['extras'])):roles[str(i+5)]=dict(role='pedestrian',radius=.22,label='P'+str(i+1))
 scenarios.append(dict(name=b['layout'],boundary=list(area.exterior.coords),bounds=list(area.bounds),axis=b['exit_axis'],plane=b['exit_plane'],roles=roles,results=results))
 print(b['layout'],{k:round(v['clearance_s'],3) for k,v in results.items()},flush=True)
data=dict(generated_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scenarios=scenarios)
(OUT/'demo_runs.json').write_text(json.dumps(data),encoding='utf-8')
template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Assistance-link movement demo</title>
<style>*{box-sizing:border-box}body{margin:0;background:#eef2f7;color:#172740;font:16px system-ui,sans-serif}main{max-width:1400px;margin:auto;padding:28px}h1{font-size:30px;margin:0 0 6px}.sub{color:#536278;margin-bottom:24px}.controls,.card,.note{background:white;border:1px solid #dce3ed;border-radius:14px;padding:18px}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:18px}select,button{font:inherit;padding:9px 14px;border-radius:8px;border:1px solid #bdcadd;background:white}button{cursor:pointer;background:#173d69;color:white}label{display:flex;gap:8px;align-items:center}.panels{display:grid;grid-template-columns:1fr 1fr;gap:18px}h2{margin:0 0 8px;font-size:21px}.desc{color:#59677a;font-size:14px;min-height:38px}canvas{display:block;width:100%;height:380px;background:#f8fafc;margin:12px 0;border-radius:8px}.stats{display:flex;gap:22px;font-size:17px}.good{color:#087958}.note{margin-top:18px;line-height:1.6}.legend{display:flex;gap:20px;margin:15px 0}.dot{display:inline-block;width:13px;height:13px;border-radius:100%;margin-right:6px}.bar{display:flex;gap:12px;align-items:center;margin-top:18px}#scrub{flex:1}#clock{font-variant-numeric:tabular-nums;min-width:110px}@media(max-width:800px){.panels{grid-template-columns:1fr}canvas{height:300px}}</style>
<main><h1>Assistance links: movement demonstration</h1><div class="sub">JuPedSim CollisionFreeSpeedModelV2 · Two helper–client pairs · Zero assumed assistance speed gain</div>
<div class="controls"><label>Layout <select id="layout"></select></label><button id="play">Pause</button><button id="reset">Restart</button><label>Playback <select id="speed"><option value=".5">0.5×</option><option value="1" selected>1×</option><option value="2">2×</option><option value="4">4×</option></select></label><label><input type="checkbox" id="links" checked> Show assistance links</label><span class="good">All eight reruns passed movement checks</span></div>
<div class="legend"><span><i class="dot" style="background:#2877d8"></i>Client (C)</span><span><i class="dot" style="background:#e98a2e"></i>Helper (H)</span><span><i class="dot" style="background:#8952ba"></i>Other pedestrian (P)</span><span>Green dashed line: exit measurement plane</span></div>
<div class="panels"><section class="card"><h2>With assistance coordination</h2><div class="desc">Helpers follow clients. Clients wait if a pair separates too far; helpers wait when too close.</div><canvas id="linked"></canvas><div class="stats" id="linkedStats"></div></section><section class="card"><h2>Independent movement control</h2><div class="desc">Same starts, geometry and nominal paces. Each person proceeds independently.</div><canvas id="independent"></canvas><div class="stats" id="independentStats"></div></section></div>
<div class="bar"><span id="clock"></span><input id="scrub" type="range" min="0" step=".02" value="0"><label><input type="checkbox" id="loop" checked> Loop</label></div>
<div class="note"><strong>What to explain:</strong> each client and helper remains a separate occupant. Compare how their spacing and exit order change when coordination is enabled. A full circle must cross the exit plane to count as exited.<br><strong>Scope:</strong> freshly rerun simulation trajectories, animated as a replay. Circular-agent escorting, not mechanical wheelchair pushing or validated human assistance. The times below are observed simulation clearance times, not ML forecasts. Coordination is not assumed to make the client faster.</div></main>
<script>const DATA=__DATA__;const labels={two_serial_door_1m:'Two pairs · 1.0 m doorway',two_serial_door_1_2m:'Two pairs · 1.2 m doorway',staggered_merge:'Mixed queue · staggered merge',two_pair_turn:'Two pairs · right-angle turn'};let s=DATA.scenarios[0],t=0,playing=true,last=null;const $=id=>document.getElementById(id);DATA.scenarios.forEach((x,i)=>{const o=document.createElement('option');o.value=i;o.textContent=labels[x.name]||x.name;$('layout').append(o)});
function duration(){return Math.max(...Object.values(s.results).map(r=>r.clearance_s))}function choose(){s=DATA.scenarios[+$('layout').value];t=0;$('scrub').max=duration();draw()}$('layout').onchange=choose;$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play'};$('reset').onclick=()=>{t=0;playing=true;$('play').textContent='Pause'};$('scrub').oninput=()=>{t=+$('scrub').value;draw()};$('links').onchange=draw;
function render(id,mode){const c=$(id),ctx=c.getContext('2d'),dpr=devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*dpr;c.height=h*dpr;ctx.scale(dpr,dpr);const r=s.results[mode];let frames=r.frames,idx=0;while(idx+1<frames.length&&frames[idx+1].t<=t)idx++;let a=frames[idx],b=frames[Math.min(idx+1,frames.length-1)],f=b.t>a.t?Math.max(0,Math.min(1,(t-a.t)/(b.t-a.t))):0;const exited=t>=r.clearance_s?Object.keys(s.roles).map(Number):a.exited;const p={};for(const [key,xy]of Object.entries(a.positions)){if(exited.includes(+key))continue;let q=b.positions[key]||xy;p[key]=[xy[0]+(q[0]-xy[0])*f,xy[1]+(q[1]-xy[1])*f]}const [x0,y0,x1,y1]=s.bounds,scale=Math.min((w-60)/(x1-x0),(h-55)/(y1-y0));const ox=(w-(x1-x0)*scale)/2,oy=(h-(y1-y0)*scale)/2;const pos=xy=>[ox+(xy[0]-x0)*scale,h-oy-(xy[1]-y0)*scale];ctx.beginPath();s.boundary.forEach((xy,i)=>{let q=pos(xy);i?ctx.lineTo(...q):ctx.moveTo(...q)});ctx.closePath();ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#344864';ctx.lineWidth=3;ctx.stroke();ctx.save();ctx.setLineDash([7,5]);ctx.strokeStyle='#17835e';ctx.lineWidth=2;ctx.beginPath();let e1=pos(s.axis===0?[s.plane,y0]:[x0,s.plane]),e2=pos(s.axis===0?[s.plane,y1]:[x1,s.plane]);ctx.moveTo(...e1);ctx.lineTo(...e2);ctx.stroke();ctx.restore();if(mode==='threshold'&&$('links').checked){ctx.strokeStyle='#7894b1';ctx.setLineDash([5,4]);ctx.lineWidth=2;for(const [u,v]of [[1,2],[3,4]])if(p[u]&&p[v]){ctx.beginPath();ctx.moveTo(...pos(p[u]));ctx.lineTo(...pos(p[v]));ctx.stroke()}ctx.setLineDash([])}for(const [key,xy]of Object.entries(p)){const role=s.roles[key],q=pos(xy);ctx.beginPath();ctx.arc(...q,role.radius*scale,0,2*Math.PI);ctx.fillStyle=role.role==='client'?'#2877d8':role.role==='helper'?'#e98a2e':'#8952ba';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1;ctx.stroke();ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillStyle='#172740';ctx.fillText(role.label,q[0],q[1]-role.radius*scale-7)}$(id+'Stats').textContent=`Exited ${exited.length} / ${r.occupants}     ·     Clearance ${r.clearance_s.toFixed(3)} s`;}
function draw(){render('linked','threshold');render('independent','independent');$('clock').textContent=t.toFixed(1)+' / '+duration().toFixed(1)+' s';$('scrub').value=t}function tick(now){if(last!==null&&playing){t+=Math.min((now-last)/1000,.1)*+$('speed').value;if(t>duration()+1){if($('loop').checked)t=0;else{t=duration();playing=false;$('play').textContent='Play'}}}last=now;draw();requestAnimationFrame(tick)}choose();requestAnimationFrame(tick);</script></html>'''
(OUT/'replay.html').write_text(template.replace('__DATA__',json.dumps(data)),encoding='utf-8')
print('Ready:',OUT/'replay.html')
